// Author: MiYu. Real source Meat Wagon orders exercise corpse manifests, research generation and carrier lifecycle cleanup.
#include "session.h"
#include "setup.h"
#include <bit>
#include <cmath>
#include <iostream>
using namespace war3;
int wmain(int argc,wchar_t** argv){
    try{
        if(argc<3 || argc>4)throw std::runtime_error("Usage: war3_corpse_cargo_tests <data-root> <fixture> [cargo|exhume|lifecycle|autocast|graveyard]");std::wstring mode=argc>3?argv[3]:L"cargo";if(mode!=L"relation-own" && mode!=L"relation-enemy" && mode!=L"relation-neutral" && mode!=L"alias-ally" && mode!=L"alias-enemy" && mode!=L"cargo" && mode!=L"exhume" && mode!=L"lifecycle" && mode!=L"autocast" && mode!=L"graveyard")throw std::runtime_error("Unknown corpse cargo mode");Archives archives(argv[1]);archives.mountMap(argv[2]);auto world=World::read(archives);auto info=world->data().info;ScriptSession session(jass::Module::compile(jass::Program::read(archives)),info);session.attachWorld(std::move(world));session.audioMuted(true);session.configure();PlayerSetup setup(info,session.config());session.applySetup(setup);session.startMain();auto& vm=session.runtime();auto call=[&](const char* name,std::initializer_list<jass::Value> args){return vm.invoke(name,{args.begin(),args.size()});};auto require=[](bool value,const char* message){if(!value)throw std::runtime_error(message);};auto type=[&](const char* code){return vm.integer(int(ObjectData::code(code)));};auto real=[&](float value){return vm.real(jass::Real::fromBits(std::bit_cast<std::uint32_t>(value)));};auto number=[](jass::Real value){return std::bit_cast<float>(value.bits());};auto corpse=[&](float x){return call("CreateCorpse",{call("Player",{vm.integer(1)}),type("hfoo"),real(x),real(0),real(0)});};if(mode==L"graveyard"){auto yard=call("CreateUnit",{call("Player",{vm.integer(0)}),type("ugrv"),real(0),real(0),real(0)});auto building=session.units().at(yard.bits);require(bool(building->graveyard),"Graveyard ability not initialized");session.advance(14);require(building->graveyard->bodies.empty(),"Graveyard generated too early");session.advance(1.1);require(building->graveyard->bodies.size()==1,"Graveyard did not generate a corpse");auto id=building->graveyard->bodies.front();require(session.units().at(id)->type==ObjectData::code("ugho") && session.corpseAvailable(id),"Graveyard did not create a usable source corpse");session.advance(60);require(building->graveyard->bodies.size()==5,"Graveyard exceeded or missed source limit");call("RemoveUnit",{vm.handle("unit",id)});session.advance(15.1);require(building->graveyard->bodies.size()==5,"Graveyard did not replace removed corpse");require(GetModuleHandleW(L"Game.dll")==nullptr,"Game.dll loaded");std::cout<<"PASS graveyard_source_interval_limit_replacement\nRESULT passed=1 failed=0 game_dll_loaded=false\n";return 0;}auto wagon=vm.global("wagon");auto carrier=session.units().at(wagon.bits);require(session.corpseCarrier(wagon.bits) && session.cargoCapacity(wagon.bits)==8,"Meat Wagon did not use source eight-slot corpse hold");auto load=[&](jass::Value body){require(call("IssueTargetOrder",{wagon,vm.string("loadcorpse"),body}).bits,"Source corpse target load order was rejected");session.advance(1.5);require(call("IsUnitInTransport",{body,wagon}).bits,"Corpse did not enter the actual carrier manifest");};
        if(mode==L"relation-own" || mode==L"relation-enemy" || mode==L"relation-neutral"){auto p0=call("Player",{vm.integer(0)}),ally=call("Player",{vm.integer(2)}),neutral=call("Player",{vm.integer(12)});call("SetPlayerAlliance",{p0,ally,vm.handle("alliancetype",0),vm.boolean(true)});call("SetPlayerAlliance",{p0,neutral,vm.handle("alliancetype",0),vm.boolean(false)});unsigned accepted=mode==L"relation-own"?0:mode==L"relation-enemy"?1:12,excluded=mode==L"relation-neutral"?0:2;auto makeCorpse=[&](unsigned owner,float x,float y){return call("CreateCorpse",{call("Player",{vm.integer(owner)}),type("hfoo"),real(x),real(y),real(0)});};auto rejected=makeCorpse(excluded,96,0);require(!call("IssueTargetOrder",{wagon,vm.string("loadcorpse"),rejected}).bits,"Corpse transport accepted excluded relation");auto permitted=makeCorpse(accepted,128,0);load(permitted);require(!call("IsUnitLoaded",{rejected}).bits,"Excluded corpse was loaded");call("RemoveUnit",{permitted});call("RemoveUnit",{rejected});auto caster=vm.global("necro");rejected=makeCorpse(excluded,96,256);require(!call("IssueImmediateOrder",{caster,vm.string("raisedead")}).bits,"Raise Dead accepted excluded relation alone");permitted=makeCorpse(accepted,128,256);require(call("IssueImmediateOrder",{caster,vm.string("raisedead")}).bits,"Raise Dead rejected permitted relation");session.advance(1.5);require(!call("GetUnitTypeId",{permitted}).bits && session.corpseAvailable(rejected.bits),"Raise Dead relation selection differed");require(!GetModuleHandleW(L"Game.dll"),"Game.dll loaded");std::cout<<"PASS corpse combined target relations\nRESULT passed=1 failed=0 game_dll_loaded=false\n";return 0;}
        if(mode==L"alias-ally" || mode==L"alias-enemy"){bool ally=mode==L"alias-ally";auto makeCorpse=[&](unsigned owner,float x,float y){return call("CreateCorpse",{call("Player",{vm.integer(owner)}),type("hfoo"),real(x),real(y),real(0)});};auto permitted=makeCorpse(ally?0:1,96,0),rejected=makeCorpse(ally?1:0,128,0);require(!call("IssueTargetOrder",{wagon,vm.string("loadcorpse"),rejected}).bits,"Corpse carrier accepted excluded relationship");load(permitted);require(!call("IsUnitLoaded",{rejected}).bits,"Corpse carrier loaded excluded relationship");call("RemoveUnit",{permitted});call("RemoveUnit",{rejected});auto caster=vm.global("necro");permitted=makeCorpse(ally?0:1,96,256);rejected=makeCorpse(ally?1:0,128,256);require(call("IssueImmediateOrder",{caster,vm.string("raisedead")}).bits,"Raise Dead rejected permitted corpse");session.advance(1.5);require(!call("GetUnitTypeId",{permitted}).bits && session.corpseAvailable(rejected.bits),"Raise Dead consumed excluded corpse or missed permitted corpse");require(!GetModuleHandleW(L"Game.dll"),"Game.dll loaded");std::cout<<"PASS corpse relationship aliases for loading and raise dead\nRESULT passed=1 failed=0 game_dll_loaded=false\n";return 0;}
        if(mode==L"cargo"){
            auto body=corpse(96);auto original=session.units().at(body.bits);load(body);double age=original->corpse->elapsed;session.advance(5);require(original->corpse->elapsed==age && original->hidden() && !session.corpseAvailable(body.bits) && session.cargoUsed(wagon.bits)==1,"Stored corpse decayed or stayed available to outside spells");require(call("IssueImmediateOrder",{wagon,vm.string("unloadallcorpses")}).bits,"Source unload all corpses order was rejected");session.advance(1.5);require(!original->transport && session.corpseAvailable(body.bits) && number(original->life)==0 && session.units().at(body.bits)==original && original->corpse->elapsed>age && !session.cargoUsed(wagon.bits),"Unloading did not preserve the original corpse and resume decay");load(body);call("UnitAddAbility",{wagon,type("Arai")});call("SetUnitState",{wagon,vm.handle("unitstate",3),real(500)});call("SetUnitState",{wagon,vm.handle("unitstate",2),real(500)});require(!call("IssueImmediateOrder",{wagon,vm.string("raisedead")}).bits,"Stored corpse was exposed to Raise Dead");std::cout<<"PASS corpse_manifest_suspend_unload_and_spell_exclusion\n";
        }else if(mode==L"exhume"){
            session.advance(16);require(!session.cargoUsed(wagon.bits),"Exhume ignored its research prerequisite");call("SetPlayerTechResearched",{call("Player",{vm.integer(0)}),type("Ruex"),vm.integer(1)});session.advance(14);require(!session.cargoUsed(wagon.bits),"Exhume generated a corpse before the source fifteen-second interval");session.advance(1.1);require(session.cargoUsed(wagon.bits)==1,"Exhume did not produce and store a real corpse");auto first=session.units().at(carrier->cargo.front());require(first->type==ObjectData::code("ugho") && first->corpse && number(first->life)==0 && !first->foodCounted,"Generated corpse lost source type, death state or population rules");session.advance(60);session.advance(1);require(session.cargoUsed(wagon.bits)==5,"Exhume did not stop at source five-corpse generation limit");session.advance(30);require(session.cargoUsed(wagon.bits)==5,"Exhume exceeded source generation limit");std::cout<<"PASS researched_source_exhume_period_type_and_limit\n";
        }else if(mode==L"autocast"){
            auto body=corpse(96);require(call("IssueImmediateOrderById",{wagon,vm.integer(852051)}).bits,"Corpse loading autocast-on order was rejected");session.advance(2);require(call("IsUnitLoaded",{body}).bits,"Corpse autocast did not load an actual corpse");require(call("IssueImmediateOrderById",{wagon,vm.integer(852052)}).bits,"Corpse loading autocast-off order was rejected");auto next=corpse(128);session.advance(2);require(!call("IsUnitLoaded",{next}).bits,"Disabled corpse autocast continued collecting");std::cout<<"PASS corpse_autocast_toggle_and_collection\n";
        }else{
            auto restored=corpse(96);load(restored);call("SetWidgetLife",{restored,real(100)});require(!call("IsUnitLoaded",{restored}).bits && !session.cargoUsed(wagon.bits) && !session.units().at(restored.bits)->corpse,"Restored transported unit retained a stale corpse cargo link");auto removed=corpse(128);load(removed);call("RemoveUnit",{removed});require(!session.cargoUsed(wagon.bits),"Removed corpse remained in the manifest");auto released=corpse(160);load(released);call("KillUnit",{wagon});require(!call("IsUnitLoaded",{released}).bits && session.corpseAvailable(released.bits),"Carrier death did not release a usable original corpse");std::cout<<"PASS corpse_resurrection_remove_and_carrier_death_cleanup\n";
        }
        if(GetModuleHandleW(L"Game.dll"))throw std::runtime_error("Game.dll loaded");std::cout<<"RESULT passed=1 failed=0 game_dll_loaded=false\n";return 0;
    }catch(const std::exception& error){std::cerr<<"FAIL "<<error.what()<<'\n';return 1;}
}
